import copy
from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    """Abstract base class for sorting algorithms using Template Method pattern."""

    def __init__(self, name: str):
        self.name = name

    @abstractmethod
    def compare(self, a: int | str, b: int | str) -> int:
        """Compare two elements. Returns negative if a < b, zero if equal, positive if a > b."""
        raise NotImplementedError

    @abstractmethod
    def swap(self, arr: list, i: int, j: int) -> None:
        """Swap elements at indices i and j in-place."""
        raise NotImplementedError

    def sort(self, arr: list) -> list:
        """Template method that orchestrates the sorting process.

        This is the entry point that defines the algorithm's skeleton:
        1. Iterate through pairs of indices.
        2. If elements are out of order (compare returns positive), swap them.
        3. Repeat until sorted.
        """
        n = len(arr)
        # Copy to avoid mutating original unless subclass overrides
        data = copy.deepcopy(arr)

        for i in range(n - 1):
            for j in range(i + 1, n):
                if self.compare(data[i], data[j]) > 0:
                    self.swap(data, i, j)
        return data


class BubbleSort(SortAlgorithm):
    """Bubble sort implementation."""

    def compare(self, a, b):
        if isinstance(a, str) or isinstance(b, str):
            return (a < b) - (a > b)  # works for strings too
        return -1 if a < b else (1 if a > b else 0)

    def swap(self, arr, i, j):
        arr[i], arr[j] = arr[j], arr[i]


class SelectionSort(SortAlgorithm):
    """Selection sort implementation."""

    def compare(self, a, b):
        if isinstance(a, str) or isinstance(b, str):
            return (a < b) - (a > b)
        return -1 if a < b else (1 if a > b else 0)

    def swap(self, arr, i, j):
        arr[i], arr[j] = arr[j], arr[i]


def main():
    # Test with integers
    int_arr = [5, 2, 8, 1, 9, 3]
    print("Original ints:", int_arr)

    bubble = BubbleSort("BubbleSort")
    sorted_bubble = bubble.sort(int_arr.copy())
    print(f"BubbleSort result: {sorted_bubble}")

    selection = SelectionSort("SelectionSort")
    sorted_selection = selection.sort(int_arr.copy())
    print(f"SelectionSort result: {sorted_selection}")

    # Test with strings
    str_arr = ["banana", "apple", "cherry"]
    print("\nOriginal strings:", str_arr)

    sorted_str_bubble = bubble.sort(str_arr.copy())
    print(f"BubbleSort strings: {sorted_str_bubble}")

    sorted_str_selection = selection.sort(str_arr.copy())
    print(f"SelectionSort strings: {sorted_str_selection}")


if __name__ == "__main__":
    main()
